"use server";

import { redirect } from "next/navigation";
import { resetPassword, verifyPasswordResetToken } from "@/lib/server/auth";
import { log } from "@/lib/server/logger";

export interface PasswordResetState {
  error: string | null;
  done?: boolean;
}

const MIN_PASSWORD_LENGTH = 10;

/**
 * Finish a one-time reset.
 *
 * The token is the authority here: it was generated by an administrator, stored
 * only as a SHA-256 hash with a one-hour expiry, and consumed by this call. No
 * session is required — the person cannot sign in, which is the whole point.
 */
export async function completePasswordResetAction(
  _previous: PasswordResetState,
  formData: FormData,
): Promise<PasswordResetState> {
  const token = String(formData.get("token") ?? "").trim();
  const password = String(formData.get("password") ?? "");
  const confirm = String(formData.get("confirm") ?? "");

  if (!token) return { error: "This link is incomplete. Ask your administrator for a new one." };
  if (password.length < MIN_PASSWORD_LENGTH) {
    return { error: `Use at least ${MIN_PASSWORD_LENGTH} characters for your new password.` };
  }
  if (password !== confirm) return { error: "The two passwords do not match. Check both and try again." };

  const verified = await verifyPasswordResetToken(token);
  if (!verified.ok) return { error: verified.message ?? "That link is no longer valid." };

  const result = await resetPassword(token, password);
  if (!result.ok) return { error: result.message ?? "The password was not changed. Try again." };

  log.info({ event: "auth.password_reset", userId: verified.userId });
  return { error: null, done: true };
}

/** Kept for pages that want a plain "go to sign-in" after the form succeeds. */
export async function backToSignIn(): Promise<void> {
  redirect("/login");
}
